 * @notice Rug-proof holder of Uniswap V3 LP position NFTs for lunch launches (UUPS-upgradeable).
 *
 * @dev SECURITY MODEL — the liquidity PRINCIPAL is locked FOREVER:
 *      This contract holds each launch's position NFTs and can only ever:
 *        1. `collect()` the accrued V3 swap fees, and
 *        2. split those fees three ways — auto-liquidity / platform / creator — where the
 *           auto-liquidity share is COMPOUNDED BACK into the same position via `increaseLiquidity`.
 *
 *      `increaseLiquidity` is purely ADDITIVE — it can only grow a position, never shrink it. There
 *      is deliberately NO code path that calls `decreaseLiquidity`, `burn`, NFT `transferFrom` /
 *      `safeTransferFrom`, or NFT `approve` / `setApprovalForAll`. So no one — owner, creator, or
 *      anyone else — can ever withdraw the underlying liquidity or the NFT. A reviewer can confirm
 *      by grepping: the only INPM selectors that touch a position are `collect` (fees) and
 *      `increaseLiquidity` (compound), plus `positions`/`ownerOf` (view).
 *
 *      The owner's ONLY powers are: set the fee split bps (hard-capped, creator always keeps >=20%),
 *      set `feeRecipient`, and authorize UUPS upgrades. None can touch the NFTs or principal.
 *
 * FEE SPLIT (of collected swap fees, in bps of 10000): `lpFeeBps` compounded back to liquidity,
 * `platformFeeBps` to `feeRecipient`, and the REMAINDER to the position's creator. Default lunch
 * config on a 1% pool = 3000 / 2000 / 5000  ==>  0.3% LP, 0.2% platform, 0.5% creator.
 */
contract LunchV3FeeLocker is
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable,
    IERC721Receiver
{
    using SafeERC20 for IERC20;

    /// @notice Hard caps: platform <= 30%, LP <= 60%, and platform+LP <= 80% (creator keeps >=20%).
    uint256 public constant MAX_PLATFORM_FEE_BPS = 3000;
    uint256 public constant MAX_LP_FEE_BPS = 6000;
    uint256 public constant MAX_TAKEN_BPS = 8000;
    /// @notice Standard burn sink for the platform's coin-token fee share (when burning is enabled).
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    INPM public npm;

    /// @notice The launcher factory allowed to register newly-minted positions.
    address public launcher;

    /// @notice Platform's share of collected swap fees, in bps.
    uint256 public platformFeeBps;
    /// @notice Share compounded back into the position (auto-liquidity), in bps.
    uint256 public lpFeeBps;
    /// @notice Recipient of the platform's fee share.
    address public feeRecipient;
    /// @notice Wrapped native (WETH) — the ETH side of every lunch V3 pool; used to index positions.
    address public weth;

    struct Position { address creator; bool active; }
    /// @notice tokenId => position record.
    mapping(uint256 => Position) public positionsInfo;
    /// @notice project token => its position NFT ids (the two launch bands).
    mapping(address => uint256[]) public tokenPositions;

    event LauncherSet(address indexed launcher);
    event PositionRegistered(uint256 indexed tokenId, address indexed creator);
    event FeeSplitSet(uint256 platformBps, uint256 lpBps);
    event FeeRecipientSet(address indexed recipient);
    event FeesCollected(
        uint256 indexed tokenId, address indexed creator, address token0, address token1,
        uint256 lp0, uint256 lp1, uint256 platform0, uint256 platform1, uint256 creator0, uint256 creator1
    );

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(
        address npm_,
        address owner_,
        address feeRecipient_,
        uint256 platformFeeBps_,
        uint256 lpFeeBps_,
        address weth_
    ) external initializer {
        require(npm_ != address(0), "npm=0");
        require(feeRecipient_ != address(0), "feeRecipient=0");
        require(weth_ != address(0), "weth=0");
        require(platformFeeBps_ <= MAX_PLATFORM_FEE_BPS && lpFeeBps_ <= MAX_LP_FEE_BPS, "bps>max");
        require(platformFeeBps_ + lpFeeBps_ <= MAX_TAKEN_BPS, "taken>max");
        __Ownable_init(owner_);
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();
        npm = INPM(npm_);
        feeRecipient = feeRecipient_;
        platformFeeBps = platformFeeBps_;
        lpFeeBps = lpFeeBps_;
        weth = weth_;
    }

    // ------------------------------------------------------------------ wiring

    /// @notice One-time set of the authorized launcher (owner only).
    function setLauncher(address launcher_) external onlyOwner {
        require(launcher == address(0), "launcher set");
        require(launcher_ != address(0), "launcher=0");
        launcher = launcher_;
        emit LauncherSet(launcher_);
    }

    /// @notice Register a freshly-minted position's creator. Only the launcher may call.
    function register(uint256 tokenId, address creator) external {
        require(msg.sender == launcher, "not launcher");
        require(creator != address(0), "creator=0");
        require(positionsInfo[tokenId].creator == address(0), "registered");
        require(npm.ownerOf(tokenId) == address(this), "not held");
        positionsInfo[tokenId] = Position({creator: creator, active: true});
        _index(tokenId);
        emit PositionRegistered(tokenId, creator);
    }

    // -------------------------------------------------- fee collection (the only value-moving action)

    /// @notice Collect + split the accrued swap fees for one position. Permissionless (funds can only
    ///         flow to the creator, the platform, or back into liquidity), so anyone may crank it.
    function collectFees(uint256 tokenId) external nonReentrant { _collect(tokenId); }

    /// @notice Collect + split fees for BOTH of a token's launch bands in one call.
    function collectAll(address token) external nonReentrant {
        uint256[] memory ids = tokenPositions[token];
        require(ids.length > 0, "no positions");
        for (uint256 i; i < ids.length; i++) _collect(ids[i]);
    }

    function _collect(uint256 tokenId) internal {
        Position memory p = positionsInfo[tokenId];
        require(p.active, "unknown position");
        (, , address token0, address token1, , , , , , , , ) = npm.positions(tokenId);

        (uint256 a0, uint256 a1) = npm.collect(INPM.CollectParams({
            tokenId: tokenId, recipient: address(this),
            amount0Max: type(uint128).max, amount1Max: type(uint128).max
        }));
        if (a0 == 0 && a1 == 0) return;

        (uint256 lp0, uint256 pl0, uint256 c0) = _split3(a0);
        (uint256 lp1, uint256 pl1, uint256 c1) = _split3(a1);

        // Auto-liquidity: compound the LP share back into THIS position (additive; can't unwind).
        // A single-sided fee only compounds when the position sits single-sided at the current tick
        // (an out-of-range band). If the position is in-range, adding one token with 0 of the other
        // reverts — so we try/catch and, on failure, route that share to the creator instead. Thus
        // collectAll never reverts and no funds are stranded.
        if (lp0 > 0 || lp1 > 0) {
            if (lp0 > 0) IERC20(token0).forceApprove(address(npm), lp0);
            if (lp1 > 0) IERC20(token1).forceApprove(address(npm), lp1);
            try npm.increaseLiquidity(INPM.IncreaseLiquidityParams({
                tokenId: tokenId, amount0Desired: lp0, amount1Desired: lp1,
                amount0Min: 0, amount1Min: 0, deadline: block.timestamp
            })) returns (uint128, uint256 used0, uint256 used1) {
                c0 += lp0 - used0; // unused (out-of-range side) -> creator
                c1 += lp1 - used1;
            } catch {
                c0 += lp0; // couldn't compound (in-range, single-sided) -> creator
                c1 += lp1;
            }
            if (lp0 > 0) IERC20(token0).forceApprove(address(npm), 0);
            if (lp1 > 0) IERC20(token1).forceApprove(address(npm), 0);
        }

        // Platform share: the WETH side always goes to feeRecipient. The coin-token side goes to
        // feeRecipient too, UNLESS burnPlatformCoinShare is on — then it's sent to DEAD (burned),
        // a deflationary sink on the platform's cut. WETH side is never burned (it's real ETH).
        {
            bool wethIs0 = token0 == weth;
            uint256 plWeth = wethIs0 ? pl0 : pl1;
            uint256 plCoin = wethIs0 ? pl1 : pl0;
            address coinTok = wethIs0 ? token1 : token0;
            if (plWeth > 0) IERC20(weth).safeTransfer(feeRecipient, plWeth);
            if (plCoin > 0) IERC20(coinTok).safeTransfer(burnPlatformCoinShare ? DEAD : feeRecipient, plCoin);
        }
        // creator share -> the creator, or split across the creator's configured recipients
        address proj = token0 == weth ? token1 : token0;
        _payCreator(token0, token1, proj, p.creator, c0, c1);

        emit FeesCollected(tokenId, p.creator, token0, token1, lp0, lp1, pl0, pl1, c0, c1);
    }

    /// @dev Split an amount into (lp, platform, creator). Creator gets the remainder.
    function _split3(uint256 amount) internal view returns (uint256 lp, uint256 platform, uint256 creator) {
        lp = (amount * lpFeeBps) / 10000;
        platform = (amount * platformFeeBps) / 10000;
        creator = amount - lp - platform;
    }

    /// @dev Record project token -> position ids (dedup). Project = the non-WETH side.
    function _index(uint256 tokenId) internal {
        (, , address t0, address t1, , , , , , , , ) = npm.positions(tokenId);
        address proj = t0 == weth ? t1 : (t1 == weth ? t0 : address(0));
        if (proj == address(0)) return;
        if (tokenCreator[proj] == address(0)) tokenCreator[proj] = positionsInfo[tokenId].creator;
        uint256[] storage arr = tokenPositions[proj];
        for (uint256 i; i < arr.length; i++) if (arr[i] == tokenId) return;
        arr.push(tokenId);
    }

    /// @notice The position ids indexed for a token.
    function positionsOf(address token) external view returns (uint256[] memory) {
        return tokenPositions[token];
    }

    // --------------------------------------------------------- owner controls (params only, never NFTs)

    function setFeeSplit(uint256 platformBps, uint256 lpBps) external onlyOwner {
        require(platformBps <= MAX_PLATFORM_FEE_BPS && lpBps <= MAX_LP_FEE_BPS, "bps>max");
        require(platformBps + lpBps <= MAX_TAKEN_BPS, "taken>max");
        platformFeeBps = platformBps;
        lpFeeBps = lpBps;
        emit FeeSplitSet(platformBps, lpBps);
    }

    function setFeeRecipient(address recipient) external onlyOwner {
        require(recipient != address(0), "recipient=0");
        feeRecipient = recipient;
        emit FeeRecipientSet(recipient);
    }

    // ------------------------------------------------------------------ NFT reception (in only)

    function onERC721Received(address, address, uint256, bytes calldata) external view override returns (bytes4) {
        require(msg.sender == address(npm), "only NPM NFTs");
        return IERC721Receiver.onERC721Received.selector;
    }

    // NOTE: there is intentionally NO decreaseLiquidity, NO burn, NO NFT transfer, and NO NFT approval
    // anywhere in this contract. The only position-touching calls are collect() and increaseLiquidity().

    // ------------------------------------------------------------------ UUPS

    error UpgradesFrozen();
    /// FROZEN: upgradeability permanently revoked. All other owner powers retained.
    function _authorizeUpgrade(address) internal pure virtual override { revert UpgradesFrozen(); }

    receive() external payable {}

    // ── Creator fee routing (appended; consumes 2 __gap slots) ──────────────────────────────
    struct Split { address to; uint256 bps; }
    /// @notice project token => its creator (the wallet that launched it). Controls the fee split.
    mapping(address => address) public tokenCreator;
    /// @notice project token => creator's fee-split recipients (bps sum to 10000). Empty = all to creator.
    mapping(address => Split[]) internal creatorSplits;

    event CreatorSplitSet(address indexed token, address indexed by, uint256 recipients);
    event TokenCreatorSet(address indexed token, address indexed from, address indexed to);

    /// @notice Owner-only: hand a coin's creator role — and with it the 0.5% creator fee stream — to
    ///         a new wallet. For community takeovers of coins whose devs have gone. Clears any split
    ///         the old creator had configured so fees can't keep paying wallets they chose.
    ///         The LP principal stays locked; this moves fee ROUTING only.
    function setTokenCreator(address token, address newCreator) external onlyOwner {
        require(newCreator != address(0), "creator=0");
        address old = tokenCreator[token];
        require(old != address(0), "unknown token");
        require(newCreator != old, "same creator");
        tokenCreator[token] = newCreator;
        uint256[] storage ids = tokenPositions[token];
        for (uint256 i; i < ids.length; i++) positionsInfo[ids[i]].creator = newCreator;
        delete creatorSplits[token];
        emit TokenCreatorSet(token, old, newCreator);
    }

    // ── Platform coin-token burn (appended; consumes 1 __gap slot) ──────────────────────────────
    /// @notice When true, the platform's COIN-TOKEN fee share is burned (→ DEAD) instead of paid to
    /// feeRecipient. The WETH (ETH) side is never burned. Owner-settable; off by default on upgrade.
    bool public burnPlatformCoinShare;
    event BurnPlatformCoinShareSet(bool enabled);

    /// @notice Toggle burning of the platform's coin-token fee share. Owner only.
    function setBurnPlatformCoinShare(bool on) external onlyOwner {
        burnPlatformCoinShare = on;
        emit BurnPlatformCoinShareSet(on);
    }

    /// @notice Creator-only: route your 0.5% creator fee to one or many wallets by bps (sum=10000).
    ///         Pass a single [wallet,10000] to redirect it entirely; pass empty arrays to reset to the
    ///         original creator. Applies to BOTH the coin and WETH sides of the fee.
    function setCreatorSplit(address token, address[] calldata recipients, uint256[] calldata bps) external {
        require(msg.sender == tokenCreator[token] && msg.sender != address(0), "not creator");
        require(recipients.length == bps.length && recipients.length <= 20, "bad len");
        delete creatorSplits[token];
        uint256 sum;
        for (uint256 i; i < recipients.length; i++) {
            require(recipients[i] != address(0) && bps[i] > 0, "bad entry");
            sum += bps[i];
            creatorSplits[token].push(Split(recipients[i], bps[i]));
        }
        require(recipients.length == 0 || sum == 10000, "bps!=10000");
        emit CreatorSplitSet(token, msg.sender, recipients.length);
    }

    /// @notice The configured creator-fee recipients for a token (empty = pays the original creator).
    function splitsOf(address token) external view returns (Split[] memory) {
        return creatorSplits[token];
    }

    /// @dev Pay the creator share, honoring a configured split. Last recipient absorbs rounding dust.
    function _payCreator(address t0, address t1, address proj, address creator, uint256 c0, uint256 c1) internal {
        Split[] storage sp = creatorSplits[proj];
        if (sp.length == 0) {
            if (c0 > 0) IERC20(t0).safeTransfer(creator, c0);
            if (c1 > 0) IERC20(t1).safeTransfer(creator, c1);
            return;
        }
        uint256 rem0 = c0; uint256 rem1 = c1; uint256 last = sp.length - 1;
        for (uint256 i; i <= last; i++) {
            uint256 a0 = i == last ? rem0 : (c0 * sp[i].bps) / 10000;
            uint256 a1 = i == last ? rem1 : (c1 * sp[i].bps) / 10000;
            rem0 -= a0; rem1 -= a1;
            if (a0 > 0) IERC20(t0).safeTransfer(sp[i].to, a0);
            if (a1 > 0) IERC20(t1).safeTransfer(sp[i].to, a1);
        }
    }

    /// @notice Metadata URI for any coin we launched: `<base><address>.json`. Address-keyed twin of
    ///         LunchV3Token.tokenURI(), and the ONLY way coins launched before that function existed
