/// @title LunchV3TokenDeployer
/// @notice External (linked) library holding LunchTokenPlain's CREATE bytecode so it lives HERE — a
///         separately-deployed, linked contract — instead of embedded in LunchV3LauncherSingle, which
///         round-35 found had grown past the EIP-170 24,576-byte runtime limit (the embedded token
///         creationCode was the bulk of the overage). Same mechanism as the V4 launcher's
///         LunchV4TokenDeployer: `deployPlain` is delegatecalled, so `address(this)` during CREATE2 is the
///         launcher — deterministic token addresses (and predictTokenAddress) are byte-identical to the
///         former inline `new`. `predictPlain` is `pure`, takes `launcher` explicitly (no delegatecall-context
///         dependence), and takes the ALREADY-FINAL CREATE2 `salt` — the SAME value the launcher passes to
///         `deployPlain` — so the salt-derivation formula lives solely in the launcher and predict==actual
///         can never drift from two independent salt formulas. The `predict==actual` fork test guards this.
library LunchV3TokenDeployer {
    function deployPlain(
        string calldata name,
        string calldata symbol,
        uint256 totalSupply,
        address launcher,
        address creator,
        bytes32 salt
    ) external returns (address) {
        return address(new LunchTokenPlain{salt: salt}(name, symbol, totalSupply, launcher, creator));
    }

    function predictPlain(
        string calldata name,
        string calldata symbol,
        uint256 totalSupply,
        address launcher,
        address creator,
        bytes32 salt
    ) external pure returns (address) {
        bytes32 initHash =
            keccak256(abi.encodePacked(type(LunchTokenPlain).creationCode, abi.encode(name, symbol, totalSupply, launcher, creator)));
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), launcher, salt, initHash)))));
    }
}

